// nextgin headless worker — generated by @nextgin/adapter. Do not edit.
//
// Boots the Next.js production router (the same one `next start` and the
// standalone server.js use, so redirects, headers, rewrites, middleware/proxy,
// ISR and Server Actions all behave identically) and listens on a Unix Domain
// Socket instead of a TCP port. The Go runtime supervises this process.
'use strict'

const http = require('node:http')
const fs = require('node:fs')
const path = require('node:path')

const dir = __dirname
const sock = process.env.NEXT_UDS_PATH
if (!sock) {
  console.error('[nextgin-worker] NEXT_UDS_PATH is required')
  process.exit(1)
}

process.env.NODE_ENV = 'production'
process.chdir(dir)

const requiredServerFiles = require(path.join(dir, '.next', 'required-server-files.json'))
// Same mechanism standalone server.js uses so next.config is not re-evaluated.
process.env.__NEXT_PRIVATE_STANDALONE_CONFIG = JSON.stringify(requiredServerFiles.config)

require('next')
// NOTE: internal Next.js API — the router server is what `next start` uses.
// The plain `next().getRequestHandler()` skips redirects/headers/middleware.
const { initialize } = require('next/dist/server/lib/router-server')

const server = http.createServer()
// Keep upstream keep-alive longer than the Go transport's idle timeout so Go
// never reuses a connection Node is about to close.
server.keepAliveTimeout = 65_000
server.headersTimeout = 66_000

function unlinkSocket() {
  try {
    fs.unlinkSync(sock)
  } catch {}
}

initialize({
  dir,
  // Used by Next for self-referential URLs; point it at the public Go port.
  port: Number(process.env.PORT || 3000),
  hostname: process.env.HOSTNAME || 'localhost',
  dev: false,
  minimalMode: false,
  server,
  keepAliveTimeout: server.keepAliveTimeout,
  quiet: true,
})
  .then(({ requestHandler, upgradeHandler }) => {
    server.on('request', (req, res) => {
      Promise.resolve(requestHandler(req, res)).catch((err) => {
        console.error('[nextgin-worker] request failed', err)
        if (!res.headersSent) res.statusCode = 500
        res.end()
      })
    })
    server.on('upgrade', (req, socket, head) => upgradeHandler(req, socket, head))

    unlinkSocket()
    server.listen(sock, () => {
      // The Go supervisor waits for exactly this line.
      process.stdout.write('NEXT_WORKER_READY\n')
    })
  })
  .catch((err) => {
    console.error('[nextgin-worker] failed to start', err)
    process.exit(1)
  })

let stopping = false
function stop() {
  if (stopping) return
  stopping = true
  server.close(() => {
    unlinkSocket()
    process.exit(0)
  })
  server.closeIdleConnections?.()
  // Hard deadline for in-flight streams.
  setTimeout(() => {
    unlinkSocket()
    process.exit(0)
  }, Number(process.env.NEXTGIN_SHUTDOWN_GRACE_MS || 10_000)).unref()
}
process.on('SIGTERM', stop)
process.on('SIGINT', stop)
process.on('exit', unlinkSocket)
